package edu.carroll.cs341.web.form;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Represents the form data submitted when a user logs in.
 * Stores the username and password entered by the user and applies
 * validation rules to ensure that both fields are provided and meet
 * their minimum length requirements.
 *
 * <p><b>Sources Used:</b></p>
 * <ul>
 *   <li>ChatGPT – Assisted with generating Javadoc comments for this file
 *   in conjunction with Max Montowski.
 *   All comments were reviewed by the author. No code was generated by ChatGPT.</li>
 * </ul>
 */
public class LoginForm {

    /** Username entered by the user; must not be null and must contain at least six characters. */
    @NotNull
    @Size(min = 6, message = "Username must be at least 2 characters long")
    private String username;

    /** Password entered by the user; must not be null and must contain at least eight characters. */
    @NotNull
    @Size(min = 8, message = "Password must be at least 8 characters long")
    private String password;

    /**
     * Retrieves the username entered in the form.
     *
     * @return the submitted username
     */
    public String getUsername() {
        return username;
    }

    /**
     * Sets the username entered in the form.
     *
     * @param username the username to store
     */
    public void setUsername(String username) {
        this.username = username;
    }

    /**
     * Retrieves the password entered in the form.
     *
     * @return the submitted password
     */
    public String getPassword() {
        return password;
    }

    /**
     * Sets the password entered in the form.
     *
     * @param password the password to store
     */
    public void setPassword(String password) {
        this.password = password;
    }
}